// 格式与本机记录纯叶测试；人工fingerprint不冒真实Acquisition或profile投递成功。
#include "resident_profile_store.hpp"
#include <iostream>
#include <stdexcept>
#include <type_traits>
using namespace hanmo::resident;
using namespace hanmo::resident::storage;
namespace {
int checks=0;
void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}
template<class T>T must(Outcome<T> value,const char* why){check(value.ok,why);return std::move(value.value);}
AdmissionCodecLimits limits(){return {6u*1024u*1024u};}
ProfileStoreLimits store_limits(){return {limits(),64,32u*1024u*1024u};}
SlotAdmissionCapsule sample(){SlotAdmissionCapsule c;c.admission_id="admission.typed";c.name_space={"profile.local",ProfilePurpose::formal,{}};c.source_world_id[0]=9;const Bytes origin{1,2,3};c.origin_snapshot_sha256=profile_sha256(origin.data(),origin.size());c.baseline_sha256=must(admission_baseline_digest(c.source_world_id,c.baseline,limits()),"empty baseline hash");return c;}
void rehash(Bytes& b){const auto digest=profile_sha256(b.data(),b.size()-32);std::copy(digest.begin(),digest.end(),b.end()-32);}
}
// 每个失败都检查明确拒绝，未知格式和合法字节的语义错误不能给物理损坏回退许可。
int main(){try{
    static_assert(!std::is_default_constructible<ProfileValidatedStage>::value,"public cannot mint admission stage");
    static_assert(!std::is_copy_constructible<ProfileValidatedStage>::value,"validated stage cannot be copied");
    auto c=sample();auto encoded=must(encode_slot_admission_capsule(c,limits()),"encode complete empty capsule");check(encoded.size()>100,"empty baseline still has complete record capsule");check(encoded[0]=='H'&&encoded[1]=='M'&&encoded[2]=='A'&&encoded[3]=='C'&&encoded[4]==1,"exact HMAC/1 marker");check(same_admission_capsule(c,must(decode_slot_admission_capsule(encoded,limits()),"decode capsule")),"exact empty round trip");
    const Bytes zeros(4,0);check(c.baseline_sha256==profile_sha256(zeros.data(),zeros.size()),"baseline hashes canonical u32 count");
    for(std::size_t n=0;n<encoded.size();++n){Bytes short_bytes(encoded.begin(),encoded.begin()+static_cast<std::ptrdiff_t>(n));check(!decode_slot_admission_capsule(short_bytes,limits()).ok,"every truncated prefix rejects");}
    auto wrong=encoded;wrong.push_back(0);check(!decode_slot_admission_capsule(wrong,limits()).ok,"trailing byte rejects");wrong=encoded;wrong[4]=2;check(!decode_slot_admission_capsule(wrong,limits()).ok,"unknown capsule version rejects");wrong=encoded;wrong.back()^=1;check(!decode_slot_admission_capsule(wrong,limits()).ok,"baseline digest tamper rejects");
    auto bad=c;bad.admission_id="";check(!encode_slot_admission_capsule(bad,limits()).ok,"empty admission ID rejects");bad=c;bad.admission_id=std::string(257,'x');check(!encode_slot_admission_capsule(bad,limits()).ok,"byte length limit");bad=c;bad.admission_id=std::string("a\0b",3);check(!encode_slot_admission_capsule(bad,limits()).ok,"NUL rejects");for(const auto& s:{std::string("\xc0\x80",2),std::string("\xed\xa0\x80",3),std::string("\xf4\x90\x80\x80",4),std::string("\xe4\xb8",2)}){bad=c;bad.admission_id=s;check(!encode_slot_admission_capsule(bad,limits()).ok,"invalid UTF8 rejects");}
    bad=c;bad.admission_id="本机.原始准入";check(encode_slot_admission_capsule(bad,limits()).ok,"valid UTF8 bytes accepted");bad=c;bad.source_world_id={};check(!encode_slot_admission_capsule(bad,limits()).ok,"zero world rejects");bad=c;bad.name_space.preview_session_id="preview";check(!encode_slot_admission_capsule(bad,limits()).ok,"formal cannot carry preview session");bad=c;bad.name_space.purpose=ProfilePurpose::author_preview;check(!encode_slot_admission_capsule(bad,limits()).ok,"preview needs actual session");bad.name_space.preview_session_id="preview.one";check(same_admission_capsule(bad,must(decode_slot_admission_capsule(must(encode_slot_admission_capsule(bad,limits()),"preview encode"),limits()),"preview decode")),"preview exact round trip");
    check(!same_profile_namespace(c.name_space,bad.name_space),"purpose is namespace identity");check(must(profile_namespace_binding(c.name_space),"formal binding")!=must(profile_namespace_binding(bad.name_space),"preview binding"),"namespace binding includes purpose/session");
    auto small=limits();small.max_capsule_bytes=encoded.size()-1;check(!encode_slot_admission_capsule(c,small).ok&&!decode_slot_admission_capsule(encoded,small).ok,"same exact byte capacity on read/write");small=limits();auto unmetered_capsule=must(encode_slot_admission_capsule(c,small),"production capsule ignores old working-memory quota");check(unmetered_capsule==encoded&&same_admission_capsule(c,must(decode_slot_admission_capsule(encoded,small),"production capsule decode without old quota")),"unmetered capsule preserves exact bytes and complete typed contents");
    EntryFingerprint f;f.key={c.source_world_id,"delivery.one"};f.entry_sha256[0]=3;c.baseline={f};c.baseline_sha256=must(admission_baseline_digest(c.source_world_id,c.baseline,limits()),"real-shaped fingerprint digest");encoded=must(encode_slot_admission_capsule(c,limits()),"nonempty fixture encode");check(same_admission_capsule(c,must(decode_slot_admission_capsule(encoded,limits()),"nonempty fixture decode")),"nonempty exact round trip");bad=c;bad.baseline.push_back(f);check(!admission_baseline_digest(bad.source_world_id,bad.baseline,limits()).ok,"duplicate identical fingerprint rejects");bad.baseline.back().entry_sha256[0]=4;check(!admission_baseline_digest(bad.source_world_id,bad.baseline,limits()).ok,"same key changed payload rejects");bad=c;bad.baseline.front().key.source_world_id[0]=1;check(!admission_baseline_digest(bad.source_world_id,bad.baseline,limits()).ok,"fingerprint belongs to same source world");
    AdmissionRecord imported;imported.capsule=c;imported.allowed_history={f};check(validate_admission_record(imported,limits()).ok,"explicit subset structurally legal");imported.allowed_history.front().entry_sha256[0]^=1;check(!validate_admission_record(imported,limits()).ok,"history exact hash membership");imported.allowed_history.clear();check(validate_admission_record(imported,limits()).ok,"empty history is valid no-consent");imported.origin=AdmissionOrigin::local_created;check(!validate_admission_record(imported,limits()).ok,"local-created cannot contain imported baseline");imported.origin=AdmissionOrigin::imported;
    check(!verify_local_admission(c,c.source_world_id,c.name_space,nullptr,limits()).ok,"capsule alone never recovers local permission");check(verify_local_admission(c,c.source_world_id,c.name_space,&imported,limits()).ok,"actual record immutable binding");auto other=c.name_space;other.purpose=ProfilePurpose::development;check(!verify_local_admission(c,c.source_world_id,other,&imported,limits()).ok,"host purpose is independent from file");auto world=c.source_world_id;world[1]=7;check(!verify_local_admission(c,world,c.name_space,&imported,limits()).ok,"checkpoint world mismatch");auto changed=imported;changed.capsule.origin_snapshot_sha256[0]^=1;check(!verify_local_admission(c,c.source_world_id,c.name_space,&changed,limits()).ok,"origin hash immutable");
    auto full=sample();full.baseline.reserve(admission_fingerprint_limit);for(std::size_t i=0;i<admission_fingerprint_limit;++i){EntryFingerprint row;row.key.source_world_id=full.source_world_id;row.key.delivery_id=std::string(250,'x')+std::to_string(100000+i);row.entry_sha256[0]=static_cast<std::uint8_t>(i);full.baseline.push_back(std::move(row));}full.baseline_sha256=must(admission_baseline_digest(full.source_world_id,full.baseline,limits()),"full 16384 baseline digest");auto bytes=must(encode_slot_admission_capsule(full,limits()),"full legal baseline encode");check(bytes.size()>4u*1024u*1024u,"capacity measures rows not 16384 bytes");check(must(decode_slot_admission_capsule(bytes,limits()),"full legal baseline decode").baseline.size()==16384,"all baseline rows retained");full.baseline.push_back(full.baseline.back());check(!admission_baseline_digest(full.source_world_id,full.baseline,limits()).ok,"16385 rows rejects");
    AdmissionRecord local;local.origin=AdmissionOrigin::local_created;local.capsule=sample();ProfileMetadataSnapshot empty;empty.name_space=local.capsule.name_space;auto one=must(insert_local_creation_record(empty,local,store_limits()),"local codec insert");check(one.generation==1&&one.records.size()==1,"first store generation");auto stored=must(encode_profile_metadata(one,store_limits()),"store encode");auto decoded=decode_profile_metadata(stored,store_limits());check(decoded.ok&&decoded.snapshot.generation==1,"store decode");check(must(insert_local_creation_record(one,local,store_limits()),"immutable retry").generation==1,"retry does not create generation");auto same_world=local;same_world.capsule.admission_id="different";check(!insert_local_creation_record(one,same_world,store_limits()).ok,"same world cannot obtain fresh local admission");same_world=local;same_world.capsule.origin_snapshot_sha256[0]^=1;check(!insert_local_creation_record(one,same_world,store_limits()).ok,"same admission cannot overwrite origin");check(!insert_local_creation_record(one,imported,store_limits()).ok,"import cannot call local creation insert");
    // 同一现有 META/1 与 META/2 生产 reader/writer 关闭工作内存账，不改档字节或 namespace。
    auto tiny_work=store_limits();
    check(must(encode_profile_metadata(one,tiny_work),"unmetered META/1 encode")==stored,"META/1 byte golden is independent of old memory quota");
    auto unmetered_one=decode_profile_metadata(stored,tiny_work);check(unmetered_one.ok&&unmetered_one.snapshot.generation==one.generation&&same_admission_capsule(unmetered_one.snapshot.records[0].capsule,one.records[0].capsule),"META/1 actual typed values retained after closing accounting");
    auto complete=one;complete.wire_version=2;auto complete_bytes=must(encode_profile_metadata(complete,store_limits()),"META/2 baseline encode");
    check(must(encode_profile_metadata(complete,tiny_work),"unmetered META/2 encode")==complete_bytes,"META/2 byte golden is independent of old memory quota");
    auto complete_read=decode_profile_metadata(complete_bytes,tiny_work);check(complete_read.ok&&complete_read.snapshot.wire_version==2&&same_admission_capsule(complete_read.snapshot.records[0].capsule,complete.records[0].capsule),"META/2 actual typed decode with small obsolete memory quota");
    // 关账不能让外来大 baseline 获得本机权限：小内存额度不再拦截，原语义拒门仍须精确生效。
    const std::size_t record_at=(sizeof("HM-META-PROFILE")-1)+2+2+8+2+one.name_space.profile_uid.size()+2+4;
    const auto old_capsule=must(encode_slot_admission_capsule(local.capsule,limits()),"old capsule for malformed-store fixture");
    Bytes foreign_store(stored.begin(),stored.begin()+static_cast<std::ptrdiff_t>(record_at));
    for(unsigned i=0;i<8;++i)foreign_store.push_back(static_cast<std::uint8_t>(bytes.size()>>(8*i)));
    foreign_store.insert(foreign_store.end(),bytes.begin(),bytes.end());
    foreign_store.insert(foreign_store.end(),stored.begin()+static_cast<std::ptrdiff_t>(record_at+8+old_capsule.size()),stored.end());rehash(foreign_store);
    auto limited_store=store_limits();
    auto oversized=decode_profile_metadata(foreign_store,limited_store);check(!oversized.ok&&oversized.code=="UnsupportedProfileDeliveryProjection","unmetered nested capsule still cannot authorize foreign delivery projection");
    oversized=decode_profile_metadata(foreign_store,store_limits());check(!oversized.ok&&oversized.code=="UnsupportedProfileDeliveryProjection","nonempty baseline refused before retaining next record");
    auto external_empty=stored;external_empty[record_at+8+old_capsule.size()]=static_cast<unsigned>(AdmissionOrigin::imported);rehash(external_empty);
    check(decode_profile_metadata(external_empty,store_limits()).code=="UnsupportedProfileDeliveryProjection","imported empty capsule cannot self-grant local creation");
    SlotBankPair banks;banks.a={true,stored,0};check(select_profile_metadata(banks,empty.name_space,store_limits()).ok,"one actual bank selection");banks.b={true,Bytes{1,2,3},0};auto selected=select_profile_metadata(banks,empty.name_space,store_limits());check(selected.ok&&selected.recovered,"physical truncated bank permits old valid bank");banks.b.bytes=stored;banks.b.bytes[sizeof("HM-META-PROFILE")-1]=3;rehash(banks.b.bytes);selected=select_profile_metadata(banks,empty.name_space,store_limits());check(!selected.ok&&selected.code=="UnsupportedProfileMetadata","unknown valid version never falls back");banks.b.bytes=stored;banks.b.bytes[banks.b.bytes.size()-33]=1;rehash(banks.b.bytes);check(!select_profile_metadata(banks,empty.name_space,store_limits()).ok,"nonempty unsupported collection never becomes empty");banks.b.bytes=stored;auto host=empty.name_space;host.profile_uid="different-host";check(!select_profile_metadata(banks,host,store_limits()).ok,"physical file cannot choose host namespace");
    check(ResidentSlotMedia::valid_slot("manual-1")&&!ResidentSlotMedia::valid_slot("profile_metadata"),"original world allowlist preserved");const auto binding=must(profile_namespace_binding(empty.name_space),"actual host binding");check(ResidentSlotMedia::valid_key({"profile_metadata",SlotFileKind::profile_metadata,binding}),"closed profile physical key");check(!ResidentSlotMedia::valid_key({"manual-1",SlotFileKind::profile_metadata,binding}),"profile cannot choose manual name");check(!ResidentSlotMedia::valid_key({"../profile_metadata",SlotFileKind::profile_metadata,binding}),"profile path escape rejects");check(!ResidentSlotMedia::valid_key({"manual-1",SlotFileKind::resident_checkpoint,binding}),"world cannot carry profile binding");
    check(!ResidentSlotMedia::valid_key({"manual-1",static_cast<SlotFileKind>(99),{}}),"unknown target kind refuses before ticket");
    std::cout<<"PROFILE_ADMISSION_CODEC_CHECKS="<<checks<<" FAILURES=0\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<": "<<e.what()<<'\n';return 1;}}
